import React from "react";
import ButtonUnstyled from '@mui/base/ButtonUnstyled';


const account = 0;

function Account(){
    console.log(account);
    if (account === 0)
    {
        return(
        <div>
            Changer de compte
            <br/>
            <CustomButton>Clement</CustomButton>
            <br/>
            <CustomButton>Alexandre</CustomButton>
            <br/>
        </div>
        )
        account=1;
    }
    if (account === 1)
    {
        return(
        <div>
            Changer de compte
            <br/>
            <CustomButton>Clement</CustomButton>
            <br/>
            <CustomButton>Alexandre</CustomButton>
            <br/>
        </div>
        )
        account=0;
    }
}

function Logout(){
    return(<Account/>)
}

export default Logout
